from functools import lru_cache

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def cost(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        @lru_cache(maxsize=None)
        def dp(i, j, r):
            if i > j:
                return 0
            if i == j:
                return 1
            best = max(dp(i + 1, j, r), dp(i, j - 1, r))
            c = cost(s[i], s[j])
            if c <= r:
                best = max(best, dp(i + 1, j - 1, r - c) + 2)
            return best

        result = dp(0, n - 1, k)
        dp.cache_clear()
        return result
